<script setup lang="ts">
import { computed, ref } from 'vue'
import Icon from './PrototypeIcon.vue'
import { departments, type HomeAction } from './data'
import { departmentDoctors, departmentProfiles, type DepartmentMode } from './department-data'
const emit = defineEmits<{ action: [action: HomeAction]; back: []; select: [department: string, doctor?: string] }>()
const selectedName = ref(departments[0]!.name), mode = ref<DepartmentMode>('ONLINE')
const selected = computed(() => departments.find(item => item.name === selectedName.value) ?? departments[0]!), profile = computed(() => departmentProfiles[selected.value.name]!), doctors = computed(() => departmentDoctors[selected.value.name] ?? [])
const todayDoctors = computed(() => doctors.value.filter(item => item.today && item.mode === mode.value)), otherDoctors = computed(() => doctors.value.filter(item => !item.today))
function choose(name: string) { selectedName.value = name; mode.value = 'ONLINE' }
function register(doctor?: string) { emit('select', selected.value.name, doctor); emit('action', 'registration') }
</script>
<template>
  <section class="ph-dept-v-c" data-testid="department-page" aria-labelledby="department-page-title"><nav class="ph-dept-c-tabs" aria-label="科室横向导航"><button v-for="item in departments" :key="item.name" :class="{ active: item.name === selected.name }" @click="choose(item.name)"><Icon :name="item.icon" />{{ item.name }}</button></nav><section class="ph-dept-c-spotlight"><div class="ph-dept-c-spotlight-copy"><span class="ph-eyebrow">DEPARTMENT SPOTLIGHT · C</span><h1 id="department-page-title">{{ selected.name }}</h1><p>{{ profile.description }}</p><div class="ph-dept-a-tags"><span v-for="item in profile.specialties" :key="item">{{ item }}</span></div><button class="ph-primary" @click="register()">立即挂号 <Icon name="arrow" /></button></div><div class="ph-dept-c-spotlight-facts"><div><strong>{{ selected.count }}</strong><small>今日出诊医生</small></div><div><strong>线上 · 线下</strong><small>服务方式</small></div><div><strong>按时段</strong><small>预约提示</small></div></div></section><section class="ph-dept-c-today"><div class="ph-dept-c-heading"><div><span class="ph-eyebrow">TODAY'S DOCTORS</span><h2>今日出诊医生</h2></div><div class="ph-dept-mode-switch" role="tablist" aria-label="今日出诊方式"><button role="tab" :aria-selected="mode === 'ONLINE'" @click="mode = 'ONLINE'">线上</button><button role="tab" :aria-selected="mode === 'OFFLINE'" @click="mode = 'OFFLINE'">线下</button></div></div><div class="ph-dept-c-today-list"><article v-for="doctor in todayDoctors" :key="doctor.id"><div class="ph-dept-c-doctor-name"><span class="ph-dept-doctor-avatar">{{ doctor.name[0] }}</span><div><h3>{{ doctor.name }}</h3><small>{{ doctor.title }} · {{ doctor.specialty }}</small></div></div><div><strong>{{ doctor.time }}</strong><small>{{ doctor.place }} · 剩余 {{ doctor.slots }} 个号</small></div><button class="ph-primary" @click="register(doctor.name)">立即挂号</button></article><p v-if="!todayDoctors.length" class="ph-dept-empty">当前方式暂无今日出诊医生。</p></div></section><section class="ph-dept-c-team"><div class="ph-dept-c-heading"><div><span class="ph-eyebrow">MEET THE TEAM</span><h2>医生列表</h2></div><button class="ph-text-button" @click="emit('action', 'doctors')">查看列表 <Icon name="arrow" /></button></div><div class="ph-dept-c-team-grid"><article v-for="doctor in otherDoctors" :key="doctor.id"><span class="ph-dept-doctor-avatar muted">{{ doctor.name[0] }}</span><h3>{{ doctor.name }} <small>{{ doctor.title }}</small></h3><p>{{ doctor.specialty }}</p><span class="ph-dept-c-next">下一次可预约：{{ doctor.time }}</span><button class="ph-dept-appointment" @click="register(doctor.name)">预约 <Icon name="arrow" /></button></article></div></section><p class="ph-directory-note"><Icon name="shield" /> 原型数据仅用于比较页面布局，实际号源以系统发布为准。</p></section>
</template>
